<?php
declare(strict_types=1);
ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';require dirname(__DIR__).'/lib/school_sms.php';
function sms_tpl_json(int $code,array $payload):never{http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())sms_tpl_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))sms_tpl_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$db=db();$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$allowedRoles=['admin','director','sub_director','headteacher'];if(!in_array($role,$allowedRoles,true))sms_tpl_json(403,['ok'=>false,'message'=>'Only school leadership can manage SMS templates.']);
$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)sms_tpl_json(422,['ok'=>false,'message'=>'Choose a school.']);$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())sms_tpl_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
$events=['fee_payment'=>'Fee payment','attendance_alert'=>'Attendance alert','exam_publication'=>'Results published','school_announcement'=>'School announcement','fee_reminder'=>'Fee reminder','contract_expiry'=>'Staff contract review'];
if($_SERVER['REQUEST_METHOD']==='GET'){$view=(string)($_GET['view']??'templates');if($view==='deliveries'){$page=max(1,filter_var($_GET['page']??1,FILTER_VALIDATE_INT)?:1);$q=$db->prepare('SELECT COUNT(*) FROM school_sms_outbox WHERE school_id=?');$q->execute([$school]);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/50));$page=min($page,$pages);$q=$db->prepare('SELECT id,event_type,status,attempts,delivery_status,created_at,last_error FROM school_sms_outbox WHERE school_id=? ORDER BY id DESC LIMIT 50 OFFSET ?');$q->bindValue(1,$school,PDO::PARAM_INT);$q->bindValue(2,($page-1)*50,PDO::PARAM_INT);$q->execute();sms_tpl_json(200,['ok'=>true,'data'=>['deliveries'=>$q->fetchAll(),'page'=>$page,'pages'=>$pages,'total'=>$total]]);}if($view!=='templates')sms_tpl_json(422,['ok'=>false,'message'=>'Choose a supported notification view.']);$q=$db->prepare('SELECT event_type,message_body,updated_at FROM school_sms_templates WHERE school_id=?');$q->execute([$school]);$saved=[];foreach($q->fetchAll() as $row)$saved[$row['event_type']]=$row; $templates=[];foreach($events as $event=>$label){$row=$saved[$event]??null;$templates[]=['event_type'=>$event,'label'=>$label,'message_body'=>$row['message_body']??school_sms_template($event),'is_custom'=>(bool)$row,'updated_at'=>$row['updated_at']??null];}sms_tpl_json(200,['ok'=>true,'data'=>['templates'=>$templates]]);}
if($_SERVER['REQUEST_METHOD']!=='POST')sms_tpl_json(405,['ok'=>false,'message'=>'Method not allowed.']);verify_csrf();$action=(string)($_POST['action']??'');$event=(string)($_POST['event_type']??'');if(!isset($events[$event]))sms_tpl_json(422,['ok'=>false,'message'=>'Choose a supported notification event.']);
try{$db->beginTransaction();$q=$db->prepare('SELECT id FROM schools WHERE id=? FOR UPDATE');$q->execute([$school]);if(!$q->fetchColumn())throw new DomainException('School not found.');if($action==='save'){$body=trim((string)($_POST['message_body']??''));$body=preg_replace('/\s+/u',' ',$body)??$body;if($body===''||mb_strlen($body)>500||preg_match('/[\x00-\x08\x0B\x0C\x0E-\x1F{}\[\]$]/u',$body))throw new DomainException('Enter a plain-text message up to 500 characters. Placeholders and control characters are not supported.');$q=$db->prepare('INSERT INTO school_sms_templates(school_id,event_type,message_body,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE message_body=VALUES(message_body),updated_by=VALUES(updated_by)');$q->execute([$school,$event,$body,$uid]);$message='SMS template saved. New notifications will use it; queued messages keep their existing copy.';$audit='update_template';$details=['school_id'=>$school,'event_type'=>$event,'customized'=>true];}elseif($action==='reset'){$q=$db->prepare('DELETE FROM school_sms_templates WHERE school_id=? AND event_type=?');$q->execute([$school,$event]);$message='Default SMS template restored for future notifications.';$audit='reset_template';$details=['school_id'=>$school,'event_type'=>$event,'customized'=>false];}else throw new DomainException('Choose save or restore default.');$q=$db->prepare("INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,'school_sms_template',?,?)");$q->execute([$uid,$audit,$school,json_encode($details,JSON_THROW_ON_ERROR)]);$db->commit();sms_tpl_json(200,['ok'=>true,'message'=>$message]);
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();sms_tpl_json($e instanceof DomainException?422:500,['ok'=>false,'message'=>$e instanceof DomainException?$e->getMessage():'The SMS template could not be saved. Apply the notification migration and retry.']);}
